from pathlib import Path
from PIL import Image,ImageOps
import html,json
root=Path(__file__).resolve().parent
source=root/'Model_Previews';dest=root/'publish/make-life-slower/docs/models';dest.mkdir(parents=True,exist_ok=True)
species={'cow':'วัว','chicken':'ไก่','duck':'เป็ด','sheep':'แกะ','goat':'แพะ','pig':'หมู','dog':'สุนัข','cat':'แมว','player':'ตัวละครผู้เล่น','seed':'คนขายเมล็ด','livestock':'คนขายสัตว์','carpenter':'ช่าง'}
cards=[]
for path in sorted(source.glob('*.png')):
    image=ImageOps.contain(Image.open(path).convert('RGB'),(1200,1200));name=path.stem+'.jpg';image.save(dest/name,quality=91,optimize=True)
    original=path.stem.startswith('Original_');raw=path.stem.removeprefix('Original_');key=raw.lower().split('_')[0]
    if raw.startswith('Seed_Merchant'):key='seed'
    if raw.startswith('Livestock_Merchant'):key='livestock'
    if raw.startswith('Farm_Carpenter'):key='carpenter'
    label=species.get(key,key.title())
    age='วัยเด็ก' if 'young' in raw.lower() or 'calf' in raw.lower() else 'เต็มวัย' if 'adult' in raw.lower() or key=='cow' else ''
    view='มุมหลัก' if 'preview' in raw.lower() else 'ด้านหน้า' if 'front' in raw.lower() else 'ด้านข้าง'
    caption=' · '.join(p for p in [label,age,view] if p)
    tags=raw.lower()+' '+caption
    cards.append(f'<article class="card" data-kind="{"original" if original else "current"}" data-tags="{html.escape(tags,quote=True)}"><button class="picture" onclick="openPicture(this)" aria-label="ขยาย {html.escape(caption,quote=True)}"><img loading="lazy" src="{name}" alt="{html.escape(caption,quote=True)}"></button><div class="caption"><strong>{html.escape(caption)}</strong><span>{"รูปต้นฉบับ" if original else "โมเดลในเกม"}</span></div></article>')
page='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>รูปโมเดล · Make Life Slower</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf2e9;color:#254334;font:16px Tahoma,system-ui,sans-serif}header{max-width:1400px;margin:auto;padding:42px 24px 18px}small{letter-spacing:2px;color:#6c8068}h1{font-size:clamp(26px,4vw,42px);margin:12px 0}p{line-height:1.7;color:#607060}.links{display:flex;gap:12px;flex-wrap:wrap}.links a,button{font:inherit}.links a{padding:13px 20px;border-radius:14px;text-decoration:none;background:#294a38;color:white}.links a.secondary{background:#dae5d7;color:#294a38}.toolbar{position:sticky;top:0;z-index:2;background:#edf2e9f5;border-bottom:1px solid #d7e1d4}.bar{max-width:1400px;margin:auto;padding:16px 24px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}.filters{display:flex;gap:6px}.filters button{border:0;border-radius:12px;background:#dce6d8;color:#294a38;cursor:pointer;padding:11px 14px}.filters button.active{background:#294a38;color:white}input{font:inherit;padding:12px 15px;border:1px solid #cad8c5;border-radius:12px;flex:1;min-width:180px;background:#fff}#count{font-size:14px;white-space:nowrap}.grid{max-width:1400px;margin:auto;padding:24px;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:22px}.card{background:white;border-radius:18px;overflow:hidden;box-shadow:0 5px 20px #294a3809}.card[hidden]{display:none}.picture{width:100%;display:block;border:0;padding:0;background:#d8e2dc;cursor:zoom-in}.picture img{width:100%;aspect-ratio:1;object-fit:contain;display:block;transition:transform .2s}.picture:hover img{transform:scale(1.025)}.caption{padding:17px;display:grid;gap:9px}.caption strong{font-size:15px;font-weight:500}.caption span{font-size:12px;color:#758571}dialog{border:0;border-radius:20px;padding:16px;background:#f6f8f2;color:#294a38;max-width:95vw;max-height:95vh}dialog::backdrop{background:#142b21c9}dialog img{display:block;max-width:85vw;max-height:75vh;object-fit:contain;border-radius:10px}.dialogbar{display:flex;align-items:center;gap:10px;padding-top:14px;justify-content:space-between}.dialogbar button{background:#294a38;color:white;border:0;padding:10px 15px;border-radius:10px;cursor:pointer}.note{max-width:1400px;padding:0 24px 30px;margin:auto;font-size:14px;color:#657963}
</style><header><small>MAKE LIFE SLOWER</small><h1>เพื่อน ๆ ในฟาร์ม</h1><p>ดูรูปโมเดลทั้งหมดที่นี่ · กดรูปเพื่อขยาย แล้วใช้ลูกศรเลื่อนไปรูปถัดไป</p><div class="links"><a href="../Model_Previews.zip" download>ดาวน์โหลดรูปทั้งหมด · ZIP 58 MB</a><a class="secondary" href="../">กลับไปเล่นเกม</a></div></header><div class="toolbar"><div class="bar"><div class="filters"><button class="active" data-filter="current" onclick="setFilter(this)">โมเดลในเกม</button><button data-filter="original" onclick="setFilter(this)">รูปต้นฉบับ</button><button data-filter="all" onclick="setFilter(this)">ทั้งหมด</button></div><input id="search" type="search" placeholder="ค้นหา เช่น แมว วัยเด็ก ช่าง" aria-label="ค้นหารูปโมเดล" oninput="filter()"><span id="count"></span></div></div><main class="grid">'''+''.join(cards)+'''</main><p class="note">โมเดลในเกม: รูปจากไฟล์ที่ใช้จริงในเกมปัจจุบัน · รูปต้นฉบับ: ภาพเรนเดอร์ก่อนลดรายละเอียดสำหรับเว็บ</p><dialog id="viewer"><img id="full" alt=""><div class="dialogbar"><button onclick="step(-1)" aria-label="รูปก่อนหน้า">ก่อนหน้า</button><span id="caption"></span><button onclick="step(1)" aria-label="รูปถัดไป">ถัดไป</button><button onclick="viewer.close()">ปิด</button></div></dialog><script>
let kind='current',index=0;const cards=[...document.querySelectorAll('.card')],viewer=document.getElementById('viewer');function filter(){const q=document.getElementById('search').value.trim().toLowerCase();cards.forEach(c=>c.hidden=(kind!=='all'&&c.dataset.kind!==kind)||!c.dataset.tags.toLowerCase().includes(q));document.getElementById('count').textContent=cards.filter(c=>!c.hidden).length+' รูป'}function setFilter(b){kind=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));filter()}function visible(){return cards.filter(c=>!c.hidden)}function show(){const card=visible()[index],img=card.querySelector('img');document.getElementById('full').src=img.src;document.getElementById('full').alt=img.alt;document.getElementById('caption').textContent=img.alt}function openPicture(b){index=visible().indexOf(b.closest('article'));show();viewer.showModal()}function step(d){index=(index+d+visible().length)%visible().length;show()}document.addEventListener('keydown',e=>{if(viewer.open&&e.key==='ArrowRight')step(1);if(viewer.open&&e.key==='ArrowLeft')step(-1)});filter();</script></html>'''
(dest/'index.html').write_text(page,encoding='utf-8')
print(json.dumps({'images':len(cards),'gallery':str(dest),'image_bytes':sum(p.stat().st_size for p in dest.glob('*.jpg'))}))
